-- Generated by apex_clothing/tools/convert.js - do not add scripts here.
--
-- This resource only carries the 3D viewer models (.glb) and texture
-- previews (.png) of the apex_clothing studio. It is separate so that
-- no single resource ever holds more than ~1024 MB of files:
-- FXServer packs a resource's files into one resource.rpf whose entry
-- offsets are 31-bit, so anything past 2 GiB corrupts the archive and
-- crashes the FiveM client (vfs-core.dll) when the studio opens.
--
-- Add to server.cfg next to the studio:   ensure apex_clothing_models
-- Re-running tools/convert.js updates this folder; never edit by hand.

fx_version 'cerulean'
game 'gta5'

author      'Apex Scriptz'
description 'apex_clothing 3D model pack (generated by tools/convert.js)'
version     '1.0.0'

files {
    'models/**/*',
}
